        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = st.nextToken();
        int m = Integer.parseInt(st.nextToken());
        String[] required = new String[m];
        for (int i = 0; i < m; i++) required[i] = st.nextToken();
        System.out.println(String.join(" ", shortestWindow(words, required)));
